<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetCodeVO;

trait SnippetAssetCodeAccessor
{
    private SnippetAssetCodeVO $_code;
    public function getCode(): string
    {
        return $this->_code->value();
    }
    public function code(): SnippetAssetCodeVO
    {
        return $this->_code;
    }
    public function isCodeChanged(?self $original = null): bool
    {
        return !$this->_code->equals($original?->_code);
    }
    public function withCode(SnippetAssetCodeVO|string $code): self
    {
        $copy = clone $this;
        $copy->_code = SnippetAssetCodeVO::from($code);
        return $copy;
    }
}
